  let h2 = h + ((1.0 - g) * band * VL_PULL * -d + g * gBand * VL_GREEN_SHIFT) * wC * v;
  let water = (1.0 - g) * band + g * gLo * hiKeep;
  let cw = smoothstepf(VL_DARK_C_LO, VL_DARK_C_HI, C);
  let w = water * cw * cw * v;
  C *= 1.0 + VL_CHROMA * w * (1.0 - g);
